    { double rr_ = fc_trirms(&o, ci, pf) * fx; if (last_t - t_start >= FC_RMAX_T0 && rr_ > FC_RMAX) fc_hw = FC_RMAX / rr_; }
#else
    if (last_t - t_start >= FC_RMAX_T0 && fc_trirms(&o, ci, pf) * fx > FC_RMAX) { tc_tri++; return 0; }
